from lib import *
S = SS('k24')
F1 = [['探针失败 ×2', 'periodSeconds=2'], ['Pod NotReady', '4.0 秒'], ['EndpointSlice', 'ready=false'], ['容器', '没有重启']]
F2 = [['探针失败 ×3', 'periodSeconds=2'], ['Killing', 'failed liveness probe'], ['重启', '7.9 秒后,exit 137'], ['新容器', 'restartCount=1']]
F3 = [['startupProbe', '每 2 秒检查 /tmp/started'], ['20 秒内', 'liveness 不执行'], ['+22.7s', 'started=True'], ['无 startupProbe', '26 秒内重启 3 次']]
F4 = [['httpGet → 404', 'Ready=False'], ['tcpSocket', '仍通过,不重启'], ['exec 超时', 'timeoutSeconds=1']]
PANELS = [('f', 'flow', '探针的效果'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
PANELS3 = [('f', 'flow', '探针的效果'), ('t', 'term', '实测输出'), ('b', 'bars', '重启次数'), ('kv', 'kv', '要点')]
steps = [
    step("readinessProbe(exec cat /tmp/ok,periodSeconds=2,failureThreshold=2)。删掉 /tmp/ok 后 4.0 秒 Pod 变成 NotReady,EndpointSlice 里该端点的 ready 从 true 变成 false,容器 restartCount 仍是 0;事件 Unhealthy(count 3):Readiness probe failed: cat: can't open '/tmp/ok'。恢复文件后 1.6 秒重新 Ready。", f=fl(F1, cur=[1, 2], done=[0], mark=[3]), t=tl(S(1), mark=lidx(S(1), '变成 NotReady', 'restartCount=0'), done=lidx(S(1), '恢复 /tmp/ok')), kv=KV([['readiness 失败', '只摘流量,不重启'], ['EndpointSlice', 'ready 条件随之变化'], ['恢复', '探针通过后立刻重新加入']], ['readiness 失败'])),
    step("livenessProbe(同样的 cat /tmp/ok,periodSeconds=2,failureThreshold=3)。删掉 /tmp/ok 后 7.9 秒容器被重启:restartCount=1,容器 ID 换了,lastState.terminated 是 Error / exitCode=137(被 SIGKILL);事件 Unhealthy ×3,然后 Killing:Container c failed liveness probe, will be restarted。新容器里命令重新创建 /tmp/ok,Ready=True。", f=fl(F2, cur=[1], done=[0], mark=[2, 3]), t=tl(S(2), mark=lidx(S(2), '7.9 秒容器被重启', 'Killing'), done=lidx(S(2), 'Ready=True')), kv=KV([['liveness 失败', '连续失败 failureThreshold 次就杀容器'], ['exitCode 137', '128 + 9:被 SIGKILL'], ['重启', '同一个 Pod,新容器']], ['liveness 失败'])),
    step("启动要 20 秒的程序:带 startupProbe 的 Pod(failureThreshold=15、period=2)——容器 started=False 一直到 +22.7 秒才变成 started=True、ready=True,期间 failureThreshold=1 的 liveness 没有执行,restartCount=0;没有 startupProbe、只有同样 liveness 的对照 Pod 在 26 秒内被重启了 3 次。", f=fl(F3, cur=[1], done=[0, 2], mark=[3]), t=tl(S(3), mark=lidx(S(3), '+22.7s', '26 秒后 restartCount=3'), done=lidx(S(3), '最终 restartCount=0')), b=bars([['有 startupProbe', 0, '0 次'], ['无 startupProbe', 3, '3 次']], 3, done=[0], mark=[1]), kv=KV([['startupProbe', '通过之前,liveness / readiness 都不执行'], ['预算', 'failureThreshold × periodSeconds = 30 秒'], ['没有它', '慢启动的程序会被 liveness 反复杀']], ['startupProbe'])),
    step("探针类型:httpGet(/healthz)加 tcpSocket(8080):删掉 /www/healthz(接口变 404,端口仍通)后 3.0 秒 Ready=False,事件 HTTP probe failed with statuscode: 404,restartCount=0——tcpSocket 的 liveness 仍通过。exec 命令要 3 秒而 timeoutSeconds=1:Ready=False,事件 command timed out … timed out after 1s。", f=fl(F4, cur=[0, 2], done=[1]), t=tl(S(4), mark=lidx(S(4), 'statuscode: 404', 'timed out after 1s'), done=lidx(S(4), 'Ready=True restartCount=0')), kv=KV([['httpGet', '状态码 200–399 才算成功'], ['tcpSocket', '只看端口能不能连上'], ['timeoutSeconds', '超时本身就算失败']], ['httpGet'])),
]
A = mkartk('k24', 24, 'Kubernetes,探针,liveness,readiness,startup,健康检查,真实验证,动画演示',
    '在 kind 集群里实测三种探针各自改变了什么:readiness 失败 4.0 秒后 Pod 变 NotReady、EndpointSlice 端点 ready=false 但容器不重启,恢复后 1.6 秒重新 Ready;liveness 失败 7.9 秒后容器被 SIGKILL 重启(exitCode 137);startupProbe 在程序启动的 22.7 秒内挡住 liveness 使 restartCount=0,而没有它的对照 Pod 26 秒内被重启 3 次;httpGet 返回 404 与 exec 超时都算失败,tcpSocket 只看端口。',
    '三种探针都叫“健康检查”,失败后的后果却完全不同:摘流量、杀容器、还是什么都不做?这篇每种都让它真的失败一次,量出多久起效、Service 的端点和容器的重启次数各发生了什么变化,并验证 startupProbe 怎么保护慢启动的程序。',
    [('4.0 s / 7.9 s', 'readiness 失败后 Pod 变 NotReady 的耗时 / liveness 失败后容器被重启的耗时(period 2 秒)'), ('exitCode 137', 'liveness 杀掉容器后 lastState.terminated 的退出码'), ('0 次 vs 3 次', '同样要 20 秒启动的程序,有 startupProbe 与没有时 26 秒内的重启次数')],
    [('readiness:只摘流量', '<p>探针命令 <code>cat /tmp/ok</code>,<code>periodSeconds: 2</code>、<code>failureThreshold: 2</code>。删掉文件 4.0 秒后 Pod 变成 <code>NotReady</code>,EndpointSlice 里这个端点的 <code>ready</code> 从 <code>true</code> 变成 <code>false</code>(Service 不再把流量发给它),容器 <code>restartCount</code> 仍是 0。恢复文件 1.6 秒后重新 <code>Ready</code>。readiness 失败是可恢复的状态,不会动容器。</p>'),
     ('liveness:杀容器', '<p>同样的探针放在 <code>livenessProbe</code>、<code>failureThreshold: 3</code>:连续失败 3 次(约 6 秒加调度误差,实测 7.9 秒)之后,kubelet 打出 <code>Killing: Container c failed liveness probe, will be restarted</code>,容器以 <code>exitCode=137</code>(128+9,被 SIGKILL)退出并重启,<code>restartCount=1</code>,容器 ID 换了。重启发生在同一个 Pod 里。</p>'),
     ('startupProbe:给启动留时间', '<p>程序要 20 秒才创建 <code>/tmp/ok</code>。只配 <code>failureThreshold: 1</code> 的 liveness,26 秒内被杀了 3 次;加上 <code>startupProbe</code>(每 2 秒一次,最多失败 15 次 = 30 秒预算)之后,<code>started</code> 一直是 <code>false</code>,到 +22.7 秒才变成 <code>true</code>、<code>ready=true</code>,期间 liveness 和 readiness 都没有执行,<code>restartCount=0</code>。慢启动的程序应该用 startupProbe 而不是把 liveness 的 <code>initialDelaySeconds</code> 设得很大。</p>'),
     ('怎样算失败', '<p><code>httpGet</code>:状态码 200~399 算成功,接口变成 404 就是失败(<code>HTTP probe failed with statuscode: 404</code>),而同一容器的 <code>tcpSocket</code> 只看端口能不能连上,仍然通过,所以 readiness 是 False、liveness 没动静。<code>exec</code> 命令的耗时超过 <code>timeoutSeconds</code> 也算失败(<code>command timed out … timed out after 1s</code>)。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);探针命令多用 exec(cat /tmp/ok),httpGet 与 tcpSocket 用 busybox httpd(端口 8080);时间用 0.2 秒间隔轮询 Pod 状态得到,包含一个轮询周期的误差;EndpointSlice 的 ready 条件读自 kubernetes.io/service-name 标签对应的 EndpointSlice;每种情形各一次',
     '没有验证:initialDelaySeconds 的效果;successThreshold 大于 1;grpc 探针;terminationGracePeriodSeconds 在 liveness 失败时的覆盖(probe-level);探针对节点资源的开销;kubelet 重启后探针状态的恢复;Pod 带 readinessGates 时的就绪判断;探针 failureThreshold 与 Service 流量中断的精确时序'],
    '三种探针', PANELS3)
